uniform float rate : 0.02 .. 0.5 = 0.1;
uniform float width : 0.02 .. 0.5 = 0.12;
uniform vec3 color : color = 1.0, 0.2, 0.1;

state float ph;
state float front;

void update() {
  ph = ph + dt * rate;
  if (ph >= 1.0) {
    ph = ph - 1.0;
    front = 0.0;
  }
  front = front + dt * 3.0;
}

vec3 shade(Led led) {
  float d = abs(led.dist - front);
  float band = smoothstep(width, 0.0, d);
  float beat = 0.5 + 0.5 * sin(ph * 6.2832);
  return color * band * beat;
}
